 function Game({mode,onClose,onDone}){
  const [attempt,setAttempt]=useState(null),[answers,setAnswers]=useState([]),[index,setIndex]=useState(0),[result,setResult]=useState(null),[error,setError]=useState(''),[remaining,setRemaining]=useState(0),[busy,setBusy]=useState(false);const saving=useRef(false),answerRef=useRef([]),attemptRef=useRef(null);
  useEffect(()=>{api('/api/campus/practice/start',{mode}).then(d=>{setAttempt(d);attemptRef.current=d;const a=d.questions.map(()=>null);setAnswers(a);answerRef.current=a;setRemaining(Math.ceil((d.expiresAt-Date.now())/1000));}).catch(e=>setError(e.message));return()=>window.speechSynthesis?.cancel();},[]);
  async function finish(){if(saving.current||!attemptRef.current)return;saving.current=true;setBusy(true);try{const d=await api('/api/campus/practice/finish',{id:attemptRef.current.id,answers:answerRef.current});setResult(d);onDone();}catch(e){setError(e.message);saving.current=false;}finally{setBusy(false);}}
  useEffect(()=>{if(!attempt||result)return;const timer=setInterval(()=>{const left=Math.max(0,Math.ceil((attempt.expiresAt-Date.now())/1000));setRemaining(left);if(left===0){clearInterval(timer);finish();}},1000);return()=>clearInterval(timer);},[attempt?.id,result]);
  const q=attempt?.questions[index];
  return <Modal title={mode==='mock'?'Level challenge':mode==='duel'?'Personal challenge':mode==='sprint'?'Orbit Sprint':'Orbit Smart'} onClose={onClose}><Notice error={error}/>{result?<div className="oc-game-result"><ObjectArt kind="trophy"/><span className="oc-eyebrow">ANOTHER STEP FORWARD.</span><h2>{Math.round(result.score/result.total*100)}<small>%</small></h2><p>{result.score} из {result.total} верно. Результат сохранён.</p><div className="oc-game-review">{result.review.map((q,i)=><div className={q.selected===q.correct?'is-correct':'is-wrong'} key={i}><b>{i+1}. {q.q}</b><p>Ответ: {q.options[q.correct]}</p><small>{q.why}</small></div>)}</div><button className="os-primary" onClick={onClose}>Продолжить путешествие</button></div>:q?<div className="oc-game-question"><div className="oc-game-timer"><span>{index+1} / {attempt.questions.length}</span><b>{Math.floor(remaining/60)}:{String(remaining%60).padStart(2,'0')}</b></div><div className="oc-progress"><i style={{width:(index+1)/attempt.questions.length*100+'%'}}/></div>{q.passage&&<blockquote>{q.passage}</blockquote>}{q.audio&&<button className="os-secondary" onClick={()=>{speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(q.audio);utterance.lang='en-GB';utterance.rate=.88;speechSynthesis.speak(utterance);}}><Icon name="headphones" size={17}/>Слушать запись</button>}<h3>{q.q}</h3><div className="oc-game-options">{q.options.map((option,i)=><button key={i} className={answers[index]===i?'is-selected':''} onClick={()=>{const next=answers.map((a,j)=>j===index?i:a);setAnswers(next);answerRef.current=next;}}><span>{String.fromCharCode(65+i)}</span>{option}</button>)}</div><div className="oc-row"><button className="os-secondary" disabled={!index||busy} onClick={()=>setIndex(index-1)}>Назад</button>{index<attempt.questions.length-1?<button className="os-primary" onClick={()=>setIndex(index+1)}>Дальше<Icon name="arrow" size={17}/></button>:<button disabled={busy} className="os-primary" onClick={finish}>{busy?'Сохраняем…':'Завершить'}</button>}</div><p className="os-help">{mode==='mock'?'Учебная проверка языка. Результат не является сертификатом IELTS.':'В рейтинг идёт лучший результат этого режима.'}</p></div>:!error&&<p>Подготавливаем вопросы…</p>}</Modal>;
 }
 function VisualLesson({lesson,onGo,onClose}){
  const [index,setIndex]=useState(0),[playing,setPlaying]=useState(false),[sound,setSound]=useState(true),[finished,setFinished]=useState(false);
  const slide=lesson.slides[index];
  useEffect(()=>{if(!playing||finished)return;let closed=false,timer;const next=()=>{if(closed)return;if(index===lesson.slides.length-1){setFinished(true);setPlaying(false);}else setIndex(i=>i+1);};if(sound&&'speechSynthesis' in window){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(slide.narration);utterance.lang='en-GB';utterance.rate=.86;utterance.onend=()=>{timer=setTimeout(next,1500);};utterance.onerror=()=>{timer=setTimeout(next,8500);};speechSynthesis.speak(utterance);}else timer=setTimeout(next,8500);return()=>{closed=true;clearTimeout(timer);window.speechSynthesis?.cancel();};},[index,playing,sound,finished]);
  return <Modal title={lesson.title+' · Visual lesson'} onClose={onClose}><div className="oc-visual-player"><Landscape variant={index%5}/><div className="oc-visual-slide" key={index}><span className="oc-eyebrow">{slide.label}</span><h3>{slide.phrase}</h3><p>{slide.explain}</p></div><div className="oc-visual-progress">{lesson.slides.map((s,i)=><button key={i} aria-label={'Сцена '+(i+1)} className={i<=index?'is-active':''} onClick={()=>{setIndex(i);setFinished(false);}}/>)}</div></div><div className="oc-visual-controls"><button className="os-secondary" onClick={()=>{if(finished){setIndex(0);setFinished(false);}setPlaying(!playing);}}><Icon name="play" size={16}/>{playing?'Пауза':finished?'Смотреть ещё раз':'Смотреть урок'}</button><button className="oc-link" onClick={()=>setSound(!sound)}>{sound?'Звук включён':'Без звука'}</button><span>{index+1} / {lesson.slides.length}</span></div><p className="os-help">Наглядная история ORBIT с озвучкой браузера. Можно переключать сцены и смотреть в своём темпе.</p><button className="os-primary" onClick={()=>{if(lesson.topic)sessionStorage.setItem('orbit-open-topic',lesson.topic);onClose();onGo(lesson.section);}}>Перейти к практике<Icon name="arrow" size={17}/></button></Modal>;
 }
